<script setup lang="ts">
import { computed, ref, watch, nextTick } from 'vue'
import { ChevronRight, ChevronLeft, Plus, X, CalendarDays } from 'lucide-vue-next'
import { state, today, future, occupied, dateLabel, type Slot } from '../operations'
import { shiftDate, weekStart, monthStart, moveMonth, monthDays, minutes, persianDay } from '../calendarDates'
const props=defineProps<{platform:string}>()
const emit=defineEmits<{create:[date:string,time:string,doctor?:string];edit:[slot:Slot]}>()
const mode=ref<'week'|'month'>('week'),anchor=ref(today()),doctor=ref(''),selectedDay=ref(today()),inspected=ref<Slot>(),inspector=ref<HTMLElement>(),lastTrigger=ref<HTMLElement>()
const doctors=computed(()=>state.doctors.filter(d=>d.platform===props.platform))
const slots=computed(()=>state.slots.filter(s=>s.platform===props.platform&&(!doctor.value||s.doctor===doctor.value)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))
const week=computed(()=>Array.from({length:7},(_,i)=>shiftDate(weekStart(anchor.value),i)))
const days=computed(()=>monthDays(anchor.value))
const heading=computed(()=>new Intl.DateTimeFormat('fa-IR',{month:'long',year:'numeric'}).format(new Date(anchor.value+'T12:00:00')))
const weekdays=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه']
const visibleSlots=computed(()=>slots.value.filter(s=>mode.value==='week'?week.value.includes(s.date):days.value.includes(s.date)))
const range=computed(()=>{const items=mode.value==='week'?visibleSlots.value:slots.value.filter(s=>s.date===selectedDay.value);return {start:Math.min(8*60,...items.map(s=>Math.floor(minutes(s.time)/60)*60)),end:Math.min(1440,Math.max(20*60,...items.map(s=>Math.ceil((minutes(s.time)+s.duration)/60)*60)))}})
const times=computed(()=>Array.from({length:(range.value.end-range.value.start)/30},(_,i)=>{const m=range.value.start+i*30;return `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}))
const booking=computed(()=>state.bookings.find(b=>b.slot===inspected.value?.id&&b.status!=='cancelled'))
const daySlots=computed(()=>slots.value.filter(s=>s.date===selectedDay.value))
const name=(id:string)=>state.doctors.find(d=>d.id===id)?.name||'متخصص'
function dayItems(date:string){return slots.value.filter(s=>s.date===date)}
function cellItems(date:string,time:string){const start=minutes(time);return slots.value.filter(s=>s.date===date&&minutes(s.time)<start+30&&minutes(s.time)+s.duration>start)}
function status(s:Slot){return occupied(s.id)?'booked':s.blocked||!future(s)||!state.doctors.find(d=>d.id===s.doctor)?.active?'blocked':'free'}
const statusText=(s:Slot)=>occupied(s.id)?'رزروشده':s.blocked?'مسدود':!future(s)?'گذشته':!state.doctors.find(d=>d.id===s.doctor)?.active?'متخصص غیرفعال':'آزاد'
function navigate(direction:number){anchor.value=mode.value==='week'?shiftDate(anchor.value,direction*7):moveMonth(anchor.value,direction);selectedDay.value=anchor.value}
function reset(){anchor.value=today();selectedDay.value=today()}
function create(date:string,time:string){emit('create',date,time,doctor.value||undefined)}
function canCreate(date:string,time:string){return future({date,time} as Slot)}
async function inspect(slot:Slot,event:Event){lastTrigger.value=event.currentTarget as HTMLElement;inspected.value=slot;await nextTick();inspector.value?.focus()}
function close(){inspected.value=undefined;lastTrigger.value?.focus()}
function edit(){if(inspected.value){emit('edit',inspected.value);inspected.value=undefined}}
function block(){if(inspected.value&&!occupied(inspected.value.id))inspected.value.blocked=!inspected.value.blocked}
function cancel(){if(booking.value&&confirm('رزرو لغو و زمان آن آزاد شود؟'))booking.value.status='cancelled'}
function trap(event:KeyboardEvent){if(event.key!=='Tab')return;const nodes=[...inspector.value!.querySelectorAll<HTMLElement>('button:not(:disabled),a[href]')];const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===inspector.value)){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
watch(()=>props.platform,()=>{doctor.value='';reset()})
</script>
<template>
<section class="appointment-calendar ops-panel"><div class="calendar-toolbar"><div class="calendar-navigation"><button type="button" aria-label="بازه قبلی" @click="navigate(-1)"><ChevronRight :size="20"/></button><div><h2>{{heading}}</h2><small v-if="mode==='week'">{{dateLabel(week[0])}} تا {{dateLabel(week[6])}}</small><small v-else>تقویم ماهانه و برنامه هر روز</small></div><button type="button" aria-label="بازه بعدی" @click="navigate(1)"><ChevronLeft :size="20"/></button></div><div class="calendar-controls"><button type="button" class="calendar-today" @click="reset">امروز</button><div class="calendar-mode" role="group" aria-label="نمای تقویم"><button :class="{active:mode==='week'}" :aria-pressed="mode==='week'" @click="mode='week'">هفتگی</button><button :class="{active:mode==='month'}" :aria-pressed="mode==='month'" @click="mode='month'">ماهانه</button></div><select v-model="doctor" aria-label="فیلتر متخصص تقویم"><option value="">همه متخصصان</option><option v-for="d in doctors" :key="d.id" :value="d.id">{{d.name}}</option></select></div></div>
<div class="calendar-legend"><span class="free">زمان آزاد</span><span class="booked">رزروشده</span><span class="blocked">مسدود یا غیرفعال</span><p>برای ایجاد وقت روی + و برای جزئیات روی نوبت کلیک کنید.</p></div>
<Transition name="flow" mode="out-in"><div :key="mode+anchor" class="calendar-view">
<div v-if="mode==='week'" class="calendar-scroll" tabindex="0" aria-label="جدول هفتگی؛ برای دیدن ساعت‌های بیشتر پیمایش کنید"><table class="week-calendar"><thead><tr><th scope="col">ساعت</th><th v-for="(date,i) in week" :key="date" scope="col" :class="{today:date===today()}"><span>{{weekdays[i]}}</span><b>{{persianDay(date).toLocaleString('fa-IR')}}</b></th></tr></thead><tbody><tr v-for="time in times" :key="time"><th scope="row" dir="ltr">{{time}}</th><td v-for="date in week" :key="date" :class="{past:!canCreate(date,time)}"><button v-for="s in cellItems(date,time)" :key="s.id" :class="['calendar-event',status(s),{continuation:minutes(s.time)<minutes(time)}]" @click="inspect(s,$event)"><b>{{minutes(s.time)<minutes(time)?'ادامه جلسه':s.time}} · {{statusText(s)}}</b><span>{{name(s.doctor)}}</span></button><button v-if="canCreate(date,time)" class="calendar-add" :aria-label="'ایجاد وقت '+dateLabel(date)+' ساعت '+time" @click="create(date,time)"><Plus :size="14"/><span>وقت جدید</span></button></td></tr></tbody></table></div>
<template v-else><div class="month-scroll"><div class="month-calendar"><strong v-for="weekday in weekdays" :key="weekday" class="month-weekday">{{weekday}}</strong><button v-for="date in days" :key="date" :class="['month-day',{outside:monthStart(date)!==monthStart(anchor),today:date===today(),selected:selectedDay===date}]" :aria-label="dateLabel(date)+'؛ '+dayItems(date).length+' نوبت'" :aria-pressed="selectedDay===date" @click="selectedDay=date"><b>{{persianDay(date).toLocaleString('fa-IR')}}</b><span v-if="dayItems(date).some(s=>status(s)==='free')" class="month-count free">{{dayItems(date).filter(s=>status(s)==='free').length.toLocaleString('fa-IR')}} آزاد</span><span v-if="dayItems(date).some(s=>status(s)==='booked')" class="month-count booked">{{dayItems(date).filter(s=>status(s)==='booked').length.toLocaleString('fa-IR')}} رزرو</span><span v-if="dayItems(date).some(s=>status(s)==='blocked')" class="month-count blocked">{{dayItems(date).filter(s=>status(s)==='blocked').length.toLocaleString('fa-IR')}} غیرفعال</span></button></div></div><section class="calendar-day-detail"><div><h3><CalendarDays :size="20"/>{{dateLabel(selectedDay)}}</h3><span>{{daySlots.length.toLocaleString('fa-IR')}} وقت تعریف‌شده؛ یک ساعت را برای ایجاد یا بررسی وقت انتخاب کنید.</span></div><div class="day-timeline"><div v-for="time in times" :key="time" class="day-time-row"><strong dir="ltr">{{time}}</strong><div><button v-for="s in cellItems(selectedDay,time)" :key="s.id" :class="['calendar-event',status(s)]" @click="inspect(s,$event)">{{name(s.doctor)}} · {{minutes(s.time)<minutes(time)?'ادامه جلسه':s.time}} · {{statusText(s)}}</button><button v-if="canCreate(selectedDay,time)" class="calendar-add" :aria-label="'ایجاد وقت '+dateLabel(selectedDay)+' ساعت '+time" @click="create(selectedDay,time)"><Plus :size="15"/>ایجاد وقت</button></div></div></div></section></template>
</div></Transition>
<Transition name="modal"><div v-if="inspected" class="modal-backdrop" @click.self="close" @keydown.esc="close"><section ref="inspector" class="editor-modal calendar-inspector" role="dialog" aria-modal="true" aria-label="جزئیات نوبت" tabindex="-1" @keydown="trap"><div class="editor-head"><h2>جزئیات زمان ویزیت</h2><button class="icon-button" aria-label="بستن جزئیات" @click="close"><X :size="20"/></button></div><span :class="['calendar-status',status(inspected)]">{{statusText(inspected)}}</span><h3>{{name(inspected.doctor)}}</h3><p>{{dateLabel(inspected.date)}} · {{inspected.time}} · {{inspected.duration.toLocaleString('fa-IR')}} دقیقه</p><p>{{inspected.mode}} · {{inspected.price.toLocaleString('fa-IR')}} تومان</p><div v-if="booking" class="calendar-booking-detail"><strong>{{booking.name}}</strong><span v-if="booking.phone">{{booking.phone}}</span><p>{{booking.note}}</p><small>کد پیگیری: {{booking.id.slice(0,8)}}</small><button v-if="booking.status==='confirmed'" class="button button-ghost" @click="cancel">لغو رزرو و آزاد کردن وقت</button></div><div v-else-if="future(inspected)" class="editor-actions"><button class="button button-ghost" @click="block">{{inspected.blocked?'آزاد کردن وقت':'مسدود کردن وقت'}}</button><button class="button button-primary" @click="edit">ویرایش زمان</button></div></section></div></Transition>
</section>
</template>
